class Solution {
public:
    bool isAlienSorted(vector<string>& words, string order) {
        int rank[26];
        for (int i = 0; i < 26; i++) {
            rank[order[i] - 'a'] = i;
        }
        for (int i = 0; i + 1 < (int)words.size(); i++) {
            const string& a = words[i];
            const string& b = words[i + 1];
            int len = (int)min(a.size(), b.size());
            int j = 0;
            while (j < len) {
                int ra = rank[a[j] - 'a'];
                int rb = rank[b[j] - 'a'];
                if (ra < rb) break;
                if (ra > rb) return false;
                j++;
            }
            if (j == len && (int)a.size() > (int)b.size()) return false;
        }
        return true;
    }
};
